const upsertProjectProgress = `-- name: UpsertProjectProgress :one
INSERT INTO prj.project_progress (
    organization_id, wbs_element_id, period_date, physical_progress_pct, created_by
) VALUES ($1, $2, $3, $4, $5)
ON CONFLICT (wbs_element_id, period_date) DO UPDATE
SET physical_progress_pct = EXCLUDED.physical_progress_pct,
    recorded_at = now(),
    updated_by = EXCLUDED.created_by
RETURNING id, row_version
`

type UpsertProjectProgressParams struct {
	OrganizationID      uuid.UUID      `json:"organization_id"`
	WbsElementID        uuid.UUID      `json:"wbs_element_id"`
	PeriodDate          pgtype.Date    `json:"period_date"`
	PhysicalProgressPct pgtype.Numeric `json:"physical_progress_pct"`
	CreatedBy           uuid.UUID      `json:"created_by"`
}

type UpsertProjectProgressRow struct {
	ID         uuid.UUID `json:"id"`
	RowVersion int32     `json:"row_version"`
}

func (q *Queries) UpsertProjectProgress(ctx context.Context, arg UpsertProjectProgressParams) (UpsertProjectProgressRow, error) {
	row := q.db.QueryRow(ctx, upsertProjectProgress,
		arg.OrganizationID,
		arg.WbsElementID,
		arg.PeriodDate,
		arg.PhysicalProgressPct,
		arg.CreatedBy,
	)
	var i UpsertProjectProgressRow
	err := row.Scan(&i.ID, &i.RowVersion)
	return i, err
}
